export function inflateCoordinates(j,t,g,h,l){l=l!==void 0?l:[];let e=0;for(let n=t;n<g;n+=h)l[e++]=j.slice(n,n+h);return l.length=e,l}export function inflateCoordinatesArray(j,t,g,h,l){l=l!==void 0?l:[];let e=0;for(let n=0,f=g.length;n<f;++n){const u=g[n];l[e++]=inflateCoordinates(j,t,u,h,l[e]),t=u}return l.length=e,l}export function inflateMultiCoordinatesArray(j,t,g,h,l){l=l!==void 0?l:[];let e=0;for(let n=0,f=g.length;n<f;++n){const u=g[n];l[e++]=u.length===1&&u[0]===t?[]:inflateCoordinatesArray(j,t,u,h,l[e]),t=u[u.length-1]}return l.length=e,l}
